package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing and adding the holidays on a sheet. */
@RestController
@RequestMapping("/api/holidays")
public class HolidayController {

    public record ListHolidaysRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record AddHolidayRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull LocalDate date) {
    }

    public record HolidayResponse(long id, LocalDate date) {
    }

    private static HolidayResponse response(Holiday holiday) {
        return new HolidayResponse(holiday.getId(), holiday.getDay());
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public List<HolidayResponse> list(@Valid @RequestBody ListHolidaysRequest req) {
        return service.list(req.sheet().trim()).stream().map(HolidayController::response).toList();
    }

    @PostMapping("/add")
    public HolidayResponse add(@Valid @RequestBody AddHolidayRequest req) {
        return response(service.add(req.sheet().trim(), req.user().trim(), req.date()));
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A holiday on a sheet: a date, at most once. */
@Entity
@Table(name = "holiday")
public class Holiday {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "holiday_date", nullable = false)
    private LocalDate day;

    protected Holiday() {
    }

    public Holiday(String sheetId, LocalDate day) {
        this.sheetId = sheetId;
        this.day = day;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public LocalDate getDay() {
        return day;
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface HolidayRepository extends JpaRepository<Holiday, Long> {

    /** The sheet's holidays, by date. */
    List<Holiday> findBySheetIdOrderByDayAsc(String sheetId);

    boolean existsBySheetIdAndDay(String sheetId, LocalDate day);
}
package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's holidays: dates added on the screen, each at most once. A claim's due-by, fixed when
 * it is created, counts business days past them (see {@link #businessDaysAfter}); a holiday added
 * later moves no claim's due-by.
 */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;

    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RoleService roles) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
        this.roles = roles;
    }

    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId);
    }

    /** Add a holiday; a date already on the sheet's list is refused (409). */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate day) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        // hold the sheet so the same date added twice at the same moment is checked one after the other
        sheetRows.findLockedById(sheetId);
        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday.");
        }
        Holiday added;
        try {
            added = holidays.saveAndFlush(new Holiday(sheetId, day));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday.");
        }
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + added.getDay());
        return added;
    }

    /**
     * The {@code days}-th business day after the date: counting forward from the day after it,
     * skipping every Saturday, Sunday and holiday on the sheet; the date itself when {@code days} is 0.
     */
    @Transactional(readOnly = true)
    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int days) {
        Set<LocalDate> off = holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(Holiday::getDay)
                .collect(Collectors.toSet());
        return businessDaysAfter(off, date, days);
    }

    /** The {@code days}-th day after the date that is no Saturday, Sunday or one of the holidays. */
    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int days) {
        LocalDate d = date;
        for (int left = days; left > 0;) {
            d = d.plusDays(1);
            if (d.getDayOfWeek() != DayOfWeek.SATURDAY && d.getDayOfWeek() != DayOfWeek.SUNDAY
                    && !holidays.contains(d)) {
                left--;
            }
        }
        return d;
    }
}
-- The sheet's holidays, each date at most once. A claim's due-by falling on one moves to the next
-- day that is not.
CREATE TABLE holiday (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE     NOT NULL,
    CONSTRAINT holiday_once UNIQUE (sheet_id, holiday_date)
);
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; none when not given.
ALTER TABLE claim ADD COLUMN tags VARCHAR(500);

-- Every tag ever used on a sheet: kept once a claim carries it, so the sheet shows its due-total
-- even when no claim carries it any more.
CREATE TABLE claim_tag_used (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(500) NOT NULL,
    CONSTRAINT claim_tag_used_unique UNIQUE (sheet_id, tag)
);
